mapper.select:
select * from (
select sm.*, m.machine_code, m.machine_name
from T_CD15_SPECIFY_MACHINE sm
left join T_CD15_MACHINE_INFO m on sm.machine_id = m.id
where sm.DEL_FLAG = 0
and m.DEL_FLAG = 0

    and INSTR(STEEL_STRIP_CODE, #{steelStripCode,jdbcType=VARCHAR}) > 0


    and MACHINE_ID = #{machineId}


    and LINE_TYPE = #{lineType}


    and JOB_TYPE = #{jobType}


    order by sm.CREATE_TIME DESC

) t


    order by ${orderStr}
